import XCTest
@testable import HRVCore

/// Blink and idle, against the reference engine.
///
/// **This file is generated** by `tools/export-swift-idle.mjs`.
///
/// Idle behaviour is the stochastic part of this engine, and the obvious way to
/// test it is by statistics — blinks a minute, gap distribution, how often two
/// come in a pair. That is the right test when two implementations cannot share
/// a random sequence.
///
/// These can. The controller takes an injectable generator, so seeding both
/// sides identically turns a statistical claim into an exact one: the same
/// timeline, behaviour for behaviour, frame for frame. Statistics would happily
/// pass a scheduler that drifted by a frame every few minutes.
final class IdleBehaviourTests: XCTestCase {

    private let tolerance = 1e-12
    private let seed: UInt32 = 20260813

    /// The generator first, because it is the part most likely to be subtly
    /// wrong. `Math.imul` is a 32-bit multiply and `>>>` a logical shift on a
    /// 32-bit value — a port reaching for a 64-bit integer type agrees for a
    /// while and then diverges, which is the worst possible failure shape.
