    func testTimelineMatchesExactly() {
        let clock = BreathClock(BreathConfig(id: "calm-4-6", inhale: 4, exhale: 6))
        var rng = Mulberry32(seed: seed)
        let idler = IdleController(random: { rng.next() })

        let dt = 1.0 / 30.0
        var produced: [(Int, String?, Double, Double, Double)] = []
        var t = 0.0
        for i in 0..<(180 * 30) {
            let out = idler.update(dt: dt, phase: clock.at(t).phase)
            if out.lid != nil || out.earTranslateY != 0 || out.tailTranslateX != 0
                || out.rootRotate != 0 {
                produced.append((i, out.lid, out.earTranslateY, out.tailTranslateX, out.rootRotate))
            }
            t += dt
        }

        XCTAssertEqual(produced.count, timeline.count, "a different number of active frames")
        for (a, b) in zip(produced, timeline) {
            XCTAssertEqual(a.0, b.0, "frame index")
            XCTAssertEqual(a.1, b.1, "lid at frame \(b.0)")
            XCTAssertEqual(a.2, b.2, accuracy: tolerance, "ears at frame \(b.0)")
            XCTAssertEqual(a.3, b.3, accuracy: tolerance, "tail at frame \(b.0)")
            XCTAssertEqual(a.4, b.4, accuracy: tolerance, "lean at frame \(b.0)")
        }
    }

    /// The counts the reference reaches over the same run. Asserted as well as
    /// the timeline because a count is what a person can sanity-check: 31
    /// blinks in 180 seconds is 10.3 a minute, and the number that
    /// matters is that it is not 4.4 — which is what the first version produced
    /// and which reads, correctly, as a character that barely blinks.
    func testBehaviourCounts() {
        let clock = BreathClock(BreathConfig(id: "calm-4-6", inhale: 4, exhale: 6))
        var rng = Mulberry32(seed: seed)
        let idler = IdleController(random: { rng.next() })
        var t = 0.0
        for _ in 0..<(180 * 30) {
            _ = idler.update(dt: 1.0 / 30.0, phase: clock.at(t).phase)
            t += 1.0 / 30.0
        }
        XCTAssertEqual(idler.counts["blink"], 31)
        XCTAssertEqual(idler.counts["earTwitch"], 10)
        XCTAssertEqual(idler.counts["tailFlick"], 7)
        XCTAssertEqual(idler.counts["weightShift"], 6)
    }

    /// Never in the first second. A character that blinks the instant an
    /// exercise starts reads as reacting to the button rather than breathing.
    func testNothingHappensInTheFirstSecond() {
        let clock = BreathClock(BreathConfig(id: "calm-4-6", inhale: 4, exhale: 6))
        var rng = Mulberry32(seed: seed)
        let idler = IdleController(random: { rng.next() })
        var t = 0.0
        while t < IdleCatalogue.leadIn {
            let out = idler.update(dt: 1.0 / 30.0, phase: clock.at(t).phase)
            XCTAssertNil(out.lid, "blinked at \(t) s")
            t += 1.0 / 30.0
        }
    }
